import{c as t,J as o,h as r,k as a}from"./chunks/framework.WgZQdPFo.js";const g=JSON.parse('{"title":"Craft Web Store & Showcase","description":"Autonomous Static Site Generator (Jamstack SSG), Quiet Luxury design system, unified Order Inbox, and multi-transport deployment in OmniCraft ERP.","frontmatter":{"title":"Craft Web Store & Showcase","description":"Autonomous Static Site Generator (Jamstack SSG), Quiet Luxury design system, unified Order Inbox, and multi-transport deployment in OmniCraft ERP.","order":9},"headers":[],"relativePath":"docs/spaces/production/web-store.md","filePath":"docs/spaces/production/web-store.md"}'),i={name:"docs/spaces/production/web-store.md"};function n(s,e,l,c,d,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="craft-web-store-showcase" tabindex="-1">Craft Web Store &amp; Showcase <a class="header-anchor" href="#craft-web-store-showcase" aria-label="Permalink to &quot;Craft Web Store &amp; Showcase&quot;">​</a></h1><p>The built-in <strong>Web Store</strong> module transforms your workshop recipe catalog, warehouse inventory, and product photography into an autonomous, lightning-fast static website without recurring subscription fees for proprietary site builders and without vulnerable server CMS platforms.</p><p>The showcase is compiled using static site generation (Jamstack SSG): the output consists of pure HTML, clean CSS, vanilla JavaScript, and optimized web-ready images. The generated website opens instantly on desktop and mobile devices, requires no database setup on your hosting server, and can be hosted for free on GitHub Pages, S3-compatible cloud storage, or standard web hosting via FTP.</p><hr><h2 id="version-v3-architecture-and-highlights" tabindex="-1">Version v3 Architecture and Highlights <a class="header-anchor" href="#version-v3-architecture-and-highlights" aria-label="Permalink to &quot;Version v3 Architecture and Highlights&quot;">​</a></h2><p>The next-generation showcase combines quiet luxury craft aesthetics with enterprise-grade engineering reliability:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Subsystem</th><th style="text-align:left;">Program Implementation</th><th style="text-align:left;">Workshop Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Quiet Luxury Design</strong></td><td style="text-align:left;">100% offline Inter WOFF2 typography, brass accents, light and dark themes with zero-flicker FOUC guard</td><td style="text-align:left;">Premium presentation for bespoke craft products with zero external CDN dependencies</td></tr><tr><td style="text-align:left;"><strong>Multi-page Structure</strong></td><td style="text-align:left;">Home storefront, faceted catalog with search, dedicated product pages, shipping/policy pages, and blog</td><td style="text-align:left;">A comprehensive brand website rather than a basic single-page price list</td></tr><tr><td style="text-align:left;"><strong>Modular Product Cards</strong></td><td style="text-align:left;">Section builder: lead summary, feature cards, craftsman story, video embed, specification table, FAQ accordion</td><td style="text-align:left;">Engaging storytelling for one-of-a-kind and serialized pieces highlighting material quality</td></tr><tr><td style="text-align:left;"><strong>Sovereign Checkout &amp; Privacy</strong></td><td style="text-align:left;">Direct Telegram/WhatsApp chats, lightweight <code>order.php</code> script, GDPR/152-FZ compliance generator</td><td style="text-align:left;">Complete legal autonomy and privacy compliance with no third-party vendor lock-in</td></tr><tr><td style="text-align:left;"><strong>Built-in Live Preview</strong></td><td style="text-align:left;">Multithreaded local HTTP server with strict no-cache headers for instant validation</td><td style="text-align:left;">Real-browser preview before deploying changes to production hosting</td></tr><tr><td style="text-align:left;"><strong>Universal Publishing Transport</strong></td><td style="text-align:left;">Local folder / ZIP, FTP/FTPS, S3 storages (Yandex Cloud, Selectel, AWS, MinIO), GitHub Pages</td><td style="text-align:left;">Rapid deployments in seconds thanks to SHA-256 incremental checksum verification</td></tr><tr><td style="text-align:left;"><strong>Unified Order Inbox</strong></td><td style="text-align:left;">Centralized incoming orders, smart clipboard parser, canned responses, and FIFO stock deduction</td><td style="text-align:left;">Zero inventory discrepancies and streamlined customer communication</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Independence from Third-Party Clouds</p><p>Unlike cloud e-commerce platforms, the <strong>OmniCraft ERP</strong> showcase cannot be disabled by platform bans, incurs no recurring monthly costs, and embeds no third-party tracking scripts. All master data resides securely on your personal computer, and the published website belongs entirely to you.</p></div><hr><h2 id="showcase-architecture-and-layout" tabindex="-1">Showcase Architecture and Layout <a class="header-anchor" href="#showcase-architecture-and-layout" aria-label="Permalink to &quot;Showcase Architecture and Layout&quot;">​</a></h2><h3 id="_1-home-storefront-and-triptych-hero" tabindex="-1">1. Home Storefront and Triptych Hero <a class="header-anchor" href="#_1-home-storefront-and-triptych-hero" aria-label="Permalink to &quot;1. Home Storefront and Triptych Hero&quot;">​</a></h3><p>The home page introduces visitors to the workshop and highlights signature pieces:</p><ul><li><strong>Triptych Hero Section:</strong> combines the workshop value proposition, featured piece photography, and three value cards (e.g., traditional saddle stitch, vegetable-tanned leather, lifetime craftsmanship guarantee).</li><li><strong>Curated Work Showcase:</strong> highlighted pieces with distinct status badges (&quot;Hit&quot;, &quot;New&quot;, &quot;Custom Order&quot;, &quot;In Stock&quot;).</li><li><strong>Master&#39;s Word Block:</strong> personal craftsman column featuring author portrait photography, philosophy quote, and signature to establish direct client trust.</li></ul><h3 id="_2-product-page-and-sticky-layout" tabindex="-1">2. Product Page and Sticky Layout <a class="header-anchor" href="#_2-product-page-and-sticky-layout" aria-label="Permalink to &quot;2. Product Page and Sticky Layout&quot;">​</a></h3><p>The product page follows an ergonomic two-column layout:</p><ul><li><strong>Left Column:</strong> interactive touch-friendly photo gallery and a stacked hierarchy of modular content sections.</li><li><strong>Right Sticky Purchase Panel:</strong> remains fixed in view during scrolling. Displays exact price, variant selectors (color, size), quantity stepper, stock availability, cart button, and direct Telegram/WhatsApp consultation shortcuts.</li><li><strong>Sticky Mobile Buy Bar:</strong> pinned to the bottom of mobile screens, allowing seamless checkout without endless scrolling back to the top.</li></ul><p>The craftsman can freely arrange modular description blocks:</p><ul><li><strong>Lead Summary:</strong> emotional, high-contrast introductory statement.</li><li><strong>Features Grid:</strong> clean icon cards detailing structural and ergonomic highlights.</li><li><strong>Craftsman Story:</strong> narrative regarding leather selection, hand burnishing, or finishing.</li><li><strong>Video Showcase:</strong> lite-facade video adapter for VK, Rutube, or YouTube. External scripts do not load until the first play click, saving bandwidth and boosting page speed.</li><li><strong>Specifications Table:</strong> structured technical matrix (dimensions, leather grade, hardware, weight).</li><li><strong>FAQ Accordion:</strong> expandable drawers addressing maintenance advice and warranty terms.</li></ul><h3 id="_3-communication-channels-checkout-and-privacy" tabindex="-1">3. Communication Channels, Checkout, and Privacy <a class="header-anchor" href="#_3-communication-channels-checkout-and-privacy" aria-label="Permalink to &quot;3. Communication Channels, Checkout, and Privacy&quot;">​</a></h3><p>The engine supports three independent checkout flows:</p><ol><li><strong>Direct Messenger Chats:</strong> customer clicks the button and jumps directly into Telegram or WhatsApp with pre-filled line items and totals. Ideal for custom orders and personal touch.</li><li><strong>Autonomous Server Script (<code>order.php</code>):</strong> for standard PHP hosting, the compiler emits a lightweight handler with an invisible Honeypot trap, IP rate limiter, and direct Telegram Bot API dispatch.</li><li><strong>National Form Services:</strong> integrated support for Yandex Forms or Web3Forms for automated lead capture.</li></ol><div class="info custom-block"><p class="custom-block-title">Privacy and Data Protection (152-FZ &amp; GDPR)</p><p>The built-in legal page generator compiles customized Privacy Policy and Terms of Service documents with your business credentials and tax ID. The checkout drawer includes a mandatory consent checkbox referencing these policies.</p></div><hr><h2 id="step-by-step-deployment-guide" tabindex="-1">Step-by-Step Deployment Guide <a class="header-anchor" href="#step-by-step-deployment-guide" aria-label="Permalink to &quot;Step-by-Step Deployment Guide&quot;">​</a></h2><h3 id="step-1-configure-profile-and-sections" tabindex="-1">Step 1. Configure Profile and Sections <a class="header-anchor" href="#step-1-configure-profile-and-sections" aria-label="Permalink to &quot;Step 1. Configure Profile and Sections&quot;">​</a></h3><ol><li>Navigate to <strong>Web Store</strong> → subtab <strong>Profile &amp; Styling</strong>.</li><li>In the vertical sidebar, select <strong>General Details</strong>: specify workshop name, tagline, city, and contacts.</li><li>In the <strong>Home Page</strong> section, configure hero text and upload the craftsman portrait for the quote block.</li><li>In the <strong>Payment &amp; Shipping</strong> section, define courier, pickup, and postal delivery options.</li><li>In the <strong>Legal Information</strong> section, enter business details and click <strong>Generate 152-FZ / Privacy Policy</strong>.</li><li>In the <strong>Theme &amp; Styling</strong> section, select default theme preference (Auto, Light, or Dark) and click <strong>Save Profile</strong>.</li></ol><h3 id="step-2-prepare-products-for-the-showcase" tabindex="-1">Step 2. Prepare Products for the Showcase <a class="header-anchor" href="#step-2-prepare-products-for-the-showcase" aria-label="Permalink to &quot;Step 2. Prepare Products for the Showcase&quot;">​</a></h3><ol><li>Open the <strong>Showcase Catalog</strong> subtab.</li><li>Select your preferred display mode in the right toolbar: <ul><li><strong>Showcase Grid 3:4:</strong> visual portrait cards showcasing items with 3:4 aspect ratio covers, marketing badges (&quot;Hit&quot;, &quot;New&quot;), and an instant publication status overlay.</li><li><strong>Compact Registry:</strong> dense tabular rows with thumbnails for quick inspection of extensive collections.</li></ul></li><li>Toggle the <strong>Publish</strong> switch for products that should appear online (accessible directly on the card cover in grid mode).</li><li>Click the configuration button (slider icon) next to the item: <ul><li>In <strong>General Properties</strong>, specify the URL slug, status badge, and retail web price.</li><li>In <strong>Photos</strong>, upload images, reorder them with ◄/► arrows, and select the card cover.</li><li>In <strong>Description Sections</strong>, add feature cards, specifications, or video demonstrations.</li></ul></li><li>Click <strong>Save Product Properties</strong>.</li></ol><h3 id="step-3-local-live-preview" tabindex="-1">Step 3. Local Live Preview <a class="header-anchor" href="#step-3-local-live-preview" aria-label="Permalink to &quot;Step 3. Local Live Preview&quot;">​</a></h3><p>Always verify your website locally prior to remote deployment:</p><ol><li>In the top showcase toolbar, click <strong>Live Preview</strong> (screen icon with arrow).</li><li>The system starts an internal multithreaded web server and opens the site in your default browser.</li><li>Test dark/light theme switching, catalog filters, and order submission flows.</li></ol><div class="warning custom-block"><p class="custom-block-title">Strict Cache Policy</p><p>The preview server sends <code>no-cache</code> and <code>must-revalidate</code> HTTP headers, ensuring that edits saved in OmniCraft ERP appear immediately upon refreshing your browser (F5).</p></div><h3 id="step-4-configure-transport-and-deploy" tabindex="-1">Step 4. Configure Transport and Deploy <a class="header-anchor" href="#step-4-configure-transport-and-deploy" aria-label="Permalink to &quot;Step 4. Configure Transport and Deploy&quot;">​</a></h3><ol><li>Open the <strong>Publishing Transport</strong> subtab.</li><li>Select your hosting method: <ul><li><strong>Local Folder / ZIP:</strong> save the site bundle to local disk for manual distribution.</li><li><strong>FTP / FTPS Protocol:</strong> direct upload to shared web hosting.</li><li><strong>S3 Cloud Storage:</strong> upload to Yandex Cloud, VK Cloud, Selectel, MinIO, or AWS S3.</li><li><strong>GitHub Pages:</strong> automatic deployment to the <code>gh-pages</code> branch using the official REST API.</li></ul></li><li>Click <strong>Test Connection</strong>. Credentials are encrypted using Windows DPAPI.</li><li>Click <strong>Save Transport</strong>, then click <strong>Publish Website</strong> in the top toolbar.</li></ol><hr><h2 id="order-inbox-workflow" tabindex="-1">Order Inbox Workflow <a class="header-anchor" href="#order-inbox-workflow" aria-label="Permalink to &quot;Order Inbox Workflow&quot;">​</a></h2><p>All orders from the website and external channels arrive in the <strong>Order Inbox</strong> subtab:</p><ol><li><strong>Website Orders:</strong> appear automatically with complete cart line items, customer details, and selected delivery method.</li><li><strong>Chat &amp; Marketplace Inquiries:</strong> copy message text to clipboard and click <strong>Smart Paste</strong>. The system extracts customer name, phone number, shipping address, and desired products.</li><li><strong>Canned Responses:</strong> click <strong>Reply</strong> to select pre-configured templates (&quot;Order Confirmed&quot;, &quot;Ready to Ship&quot;, &quot;Bank Details&quot;) with direct 1-click jump to Telegram or WhatsApp.</li><li><strong>1-Click FIFO Stock Deduction:</strong> after shipping the package, click <strong>Complete Sale</strong>. The system automatically deducts finished goods from warehouse inventory using the FIFO method and logs revenue in Cash Flow (DDS).</li></ol>',38)])])}const p=t(i,[["render",n]]);export{g as __pageData,p as default};
